import json, html
from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
root=Path(r'D:\MeroTelecom\output\playwright\capstone-2026-10-06')
cases=json.loads((root/'focused-test-results.json').read_text(encoding='utf-8-sig'))
style='''body{margin:0;background:#eef1f5;font:16px Arial,sans-serif;color:#172233}main{margin:32px auto;width:1120px;background:white;border:1px solid #ccd4de;border-radius:10px;overflow:hidden}header{padding:24px 30px;border-bottom:1px solid #ccd4de;background:#10243b;color:white}h1{font-size:28px;margin:9px 0}h2{font-size:18px;margin:0}.meta{padding:20px 30px;background:#f7fafc;line-height:1.6}.warning{margin:18px 30px;padding:14px;background:#fff4da;border:1px solid #dfbd73;border-radius:6px;line-height:1.5}.stats{display:flex;gap:38px;margin-top:12px}.stats b{font-size:24px;color:#14723d}pre{margin:20px 30px 28px;font:14px/1.65 Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere}footer{padding:15px 30px;border-top:1px solid #ccd4de;color:#546477;font-size:13px}a{color:#1764aa}li{line-height:2}'''
for c in cases:
 raw=(root/(c['id']+'-console.txt')).read_text(encoding='utf-8-sig')
 date=datetime.fromisoformat(c['startedUtc'].replace('Z','+00:00')).astimezone(ZoneInfo('Australia/Adelaide')).strftime('%d %B %Y, %I:%M %p %Z')
 status='PASSED' if c['exitCode']==0 else 'FAILED'
 text=f'''<!doctype html><html><meta charset="utf-8"><title>{c['id']} - Automated test evidence</title><style>{style}</style><main><header><h2>MERO TELECOM | EXECUTED AUTOMATED TEST EVIDENCE</h2><h1>{c['id']} — {html.escape(c['name'])}</h1>Existing Jest tests executed against project code</header><div class="meta">Run: {date}<br>Scope: <strong>unit/service tests with mocked dependencies</strong><div class="stats"><span><b>{status}</b><br>Automated test run</span><span><b>{c['passed']}</b><br>Assertions passed</span><span><b>{c['failed']}</b><br>Assertions failed</span><span><b>{c['durationSeconds']}s</b><br>Elapsed time</span></div></div><div class="warning"><strong>Full browser acceptance is blocked.</strong> Docker/WSL failed with ERROR_NO_SYSTEM_RESOURCES and localhost:3000 refused the connection. This screenshot records an actual automated test run. It does not show the application workflow, a live payment, or live NBN/MNF provisioning.</div><pre>{html.escape(raw)}</pre><footer>Source: {c['id']}-console.txt and {c['id']}-jest.json. Screenshot captured in Chromium. Raw results are included.</footer></main></html>'''
 (root/(c['id']+'-automated.html')).write_text(text,encoding='utf-8')
rows=''.join(f'<li><a href="{c["id"]}-automated.png">{c["id"]} — {html.escape(c["name"])}</a>: {c["passed"]} passed, {c["failed"]} failed. <a href="{c["id"]}-console.txt">Raw log</a> · <a href="{c["id"]}-jest.json">Jest JSON</a></li>' for c in cases)
(root/'index.html').write_text(f'<!doctype html><meta charset="utf-8"><title>Mero Telecom test evidence</title><style>{style}</style><main><header><h1>Mero Telecom — test evidence</h1>6 October 2026</header><div class="warning"><strong>Supporting automated evidence only.</strong> Full application browser tests remain blocked by Docker/WSL ERROR_NO_SYSTEM_RESOURCES. These screenshots show real executions of existing unit/service tests using mocked dependencies.</div><div class="meta"><strong>{sum(c["passed"] for c in cases)} tests passed; {sum(c["failed"] for c in cases)} failed.</strong><ol>{rows}</ol></div></main>',encoding='utf-8')
print(f'Generated {len(cases)} evidence pages from actual Jest output; {sum(c["passed"] for c in cases)} tests passed.')
